<script setup lang="ts">
import { hrDocumentListRouteQuery, useHrDocuments } from '@/composables/useHrDocuments'
import { useHrDepartments } from '@/composables/useHrDepartments'
import { refDebounced } from '@vueuse/core'
import { returnToQuery } from '@/utils/safeReturnTo'
import { hasPendingHrSearch, hrCommittedListParams } from '@/composables/useHrSearch'
const route = useRoute(); const router = useRouter(); const { t } = useI18n(); const hydrated = useHydrated(); const { can } = useAccess()
const search = ref(String(route.query.q ?? '')); const debouncedSearch = refDebounced(search, 250); const hasPendingSearch = computed(() => hasPendingHrSearch(search.value, route.query.q)); const departmentId = ref(route.query.department_id ? Number(route.query.department_id) : undefined); const limit = 25; const offset = ref(Math.max(0, Number(route.query.offset ?? 0) || 0))
const committedListParams = computed(() => hrCommittedListParams(route.query)); const committedDepartmentId = computed(() => route.query.department_id ? Number(route.query.department_id) : undefined)
const query = useHrDocuments(computed(() => ({ q: committedListParams.value.q, department_id: committedDepartmentId.value, limit, offset: committedListParams.value.offset }))); const departments = useHrDepartments()
const page = computed(() => Math.floor(committedListParams.value.offset / limit) + 1); const pages = computed(() => Math.max(1, Math.ceil((query.data.value?.total ?? 0) / limit)))
watch(() => [route.query.q, route.query.department_id, route.query.offset], ([q, department, nextOffset]) => { search.value = String(q ?? ''); departmentId.value = department ? Number(department) : undefined; offset.value = Math.max(0, Number(nextOffset ?? 0) || 0) })
watch(debouncedSearch, (value) => { if (value !== String(route.query.q ?? '')) updateFilters() })
function updateFilters() { offset.value = 0; void router.replace({ query: hrDocumentListRouteQuery(route.query, { q: search.value, department_id: departmentId.value, offset: 0 }) }) }
function updateDepartment(event: Event) { const value = (event.target as HTMLSelectElement).value; departmentId.value = value ? Number(value) : undefined; updateFilters() }
function setPage(next: number) { if (!hydrated.value || query.isFetching.value || hasPendingSearch.value || next < 1 || next > pages.value) return; offset.value = (next - 1) * limit; void router.replace({ query: hrDocumentListRouteQuery(route.query, { q: search.value, department_id: departmentId.value, offset: offset.value }) }) }
</script>
<template><div class="nasq-page-stack mx-auto w-full max-w-[1440px]"><SharedPageHeader :title="t('hr.docs.title')" :back-to="'/hr'"><NuxtLink v-if="can('hr.documents.manage')" :to="{ path: '/hr/documents/new', query: { ...returnToQuery(route.fullPath), department_id: departmentId } }"><Button :disabled="!hydrated">{{ t('hr.docs.new') }}</Button></NuxtLink></SharedPageHeader><div class="nasq-toolbar nasq-panel flex min-w-0 flex-wrap items-center"><Input v-model="search" :disabled="!hydrated" :placeholder="t('hr.docs.search')" class="min-w-0 flex-1 sm:min-w-56" /><select v-if="can('hr.departments.read')" :aria-label="t('hr.directory.allDepartments')" :value="departmentId ?? ''" class="h-9 w-full min-w-0 rounded-md border border-input bg-background px-3 text-sm sm:w-auto sm:min-w-48" :disabled="!hydrated" @change="updateDepartment"><option value="">{{ t('hr.directory.allDepartments') }}</option><option v-for="department in departments.data.value?.items ?? []" :key="department.id" :value="department.id">{{ department.name }}</option></select></div><SharedPageState :loading="query.isLoading.value" :error="query.error.value" :empty="!query.data.value?.items.length" @retry="query.refetch"><div class="nasq-panel overflow-hidden"><NuxtLink v-for="document in query.data.value?.items" :key="document.id" :to="{ path: `/hr/departments/${document.department.id}/documents/${document.id}`, query: returnToQuery(route.fullPath) }" class="flex min-w-0 items-center gap-3 border-b border-border/80 p-3 last:border-0 transition-colors hover:bg-muted/70"><span class="min-w-0 truncate font-medium">{{ document.name }}</span><span class="ms-2 min-w-0 truncate text-sm text-muted-foreground">{{ document.department.name }}</span></NuxtLink></div></SharedPageState><div v-if="pages > 1" class="flex items-center justify-between text-sm text-muted-foreground"><Button variant="ghost" :disabled="!hydrated || hasPendingSearch || page === 1 || query.isFetching.value" @click="setPage(page - 1)">{{ t('access.previousPage') }}</Button><span>{{ t('access.pageOf', { page, pages }) }}</span><Button variant="ghost" :disabled="!hydrated || hasPendingSearch || page >= pages || query.isFetching.value" @click="setPage(page + 1)">{{ t('access.nextPage') }}</Button></div></div></template>
